mapper.select:
SELECT c.id AS card_id, c.user_id AS user_id, u.name AS owner_name, u.role AS owner_role, cp.id AS card_product_id, cp.company AS company, COALESCE(c.card_name, cp.name) AS card_name, cp.annual_fee AS annual_fee, cp.image AS image, JSON_UNQUOTE(JSON_EXTRACT(cp.benefit, '$')) AS benefit, cp.`condition` AS condition_text, DATE_FORMAT(cp.updated_at, '%Y-%m-%d %H:%i:%s') AS condition_checked_at FROM card c INNER JOIN `user` u ON u.id = c.user_id INNER JOIN card_product cp ON cp.id = c.card_product_id WHERE c.card_product_id IS NOT NULL AND c.user_id IN
#{userId}
ORDER BY c.user_id ASC, cp.company ASC, COALESCE(c.card_name, cp.name) ASC, c.id ASC

SELECT c.id AS card_id, GREATEST( COALESCE(SUM( CASE WHEN cr.type = 'EXPENSE' THEN cr.amount WHEN cr.type = 'INCOME' THEN -cr.amount ELSE 0 END ), 0), 0 ) AS recognized_performance_amount FROM card c LEFT JOIN card_record cr ON cr.card_id = c.id AND cr.record_date >= #{startDate} AND cr.record_date <= #{endDate} AND cr.type IN ('EXPENSE', 'INCOME') WHERE c.id IN
#{cardId}
GROUP BY c.id

mapper.update:
UPDATE card_product
SET annual_fee = #{source.annualFee},
    image = #{source.image},
    benefit = #{source.benefit},
    `condition` = #{source.conditionText}
WHERE company = #{source.company}
  AND name = #{source.name}
